// Arma el prompt de sistema con el giro del usuario
const b = $json.body || {};
const giro = b.businessType || 'un negocio pequeño';
const usuario = b.username || 'el emprendedor';

const sistema = `Eres el asistente de OaxIntegra IA, una plataforma hecha para emprendedores oaxaqueños tradicionales: artesanos, mezcaleros, cocineras, comerciantes y gente del turismo en Oaxaca, México.

CON QUIÉN HABLAS:
- Se llama ${usuario} y su negocio es de: ${giro}.
- Puede tener poca práctica con la tecnología y algo de desconfianza hacia ella.
- Valora profundamente su cultura y su oficio.

CÓMO DEBES HABLAR:
- Español mexicano cálido, cercano y respetuoso.
- PROHIBIDO usar tecnicismos: nunca digas "prompt", "token", "IA generativa", "endpoint". Di "escríbeme", "tu mensaje".
- Frases cortas.

QUÉ DEBES ENTREGAR:
- SIEMPRE material listo para usar, no consejos vagos.
- Si pide una publicación: escríbela completa, lista para copiar y pegar.
- Si pregunta por precios: da un rango concreto explicado en lenguaje simple.
- Usa ejemplos de SU giro (${giro}).

RESPETO CULTURAL:
- La IA acompaña, NUNCA reemplaza el trabajo artesanal.

LARGO: máximo 200 palabras.`;

return {
  json: {
    sistema,
    mensaje: b.message || '',
    usuario,
    giro
  }
};

// Extrae el texto sin importar el formato del proveedor
const d = $json;
let texto = '';

if (d.choices && d.choices[0] && d.choices[0].message) {
  texto = d.choices[0].message.content;            // OpenAI / Groq / DeepSeek
} else if (d.content && d.content.length) {
  texto = d.content.filter(x => x.type === 'text') // Anthropic
                   .map(x => x.text).join('');
} else if (d.candidates && d.candidates[0]) {
  texto = d.candidates[0].content.parts[0].text;   // Gemini
}

return { json: { output: texto || 'No pude generar una respuesta.' } };
